# Regenerate src/deployments.ts from deployments/arc-testnet.json + .circle/wallets.json (ids/addresses only).
import json, os
root = os.path.join(os.path.dirname(__file__), "../..")
w = json.load(open(os.path.join(root, ".circle/wallets.json")))
d = json.load(open(os.path.join(root, "deployments/arc-testnet.json")))
open(os.path.join(root, "agent/src/deployments.ts"), "w").write(
    "// Generated by scripts/gen-deployments.py. Wallet ids are not secrets\n"
    "// (using them requires CIRCLE_API_KEY + CIRCLE_ENTITY_SECRET).\n"
    "export const deployments = " + json.dumps(d, indent=2) + ";\n\n"
    "export const circleWalletSet = " + json.dumps(w, indent=2) + ";\n")
